<script setup>
import { computed, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
const props=defineProps({mode:{type:String,default:'sign-in'}});const router=useRouter();const email=ref('');const password=ref('');const name=ref('');const role=computed(()=>props.mode==='mentor'?'mentor':'student');const submitted=ref(false);const title=computed(()=>({ 'sign-in':'Welcome back.','register':'How would you like to use Waypoint?','student':'Create your student account.','mentor':'Become a Waypoint mentor.','forgot':'Reset your password.','reset':'Choose a new password.'}[props.mode]||'Welcome to Waypoint.'));const submit=()=>{submitted.value=true;if(props.mode==='student'||props.mode==='mentor')router.push(props.mode==='student'?'/student':'/mentor')};const steps=computed(()=>role.value==='student'?['Create your account','Build your profile','Describe what you need','The IIC team reviews']:['Create your account','Set up your mentoring profile','Set availability and capacity','Accept or decline proposals'])
</script>
<template><div class="auth-layout"><aside class="auth-story"><RouterLink to="/" class="auth-brand">↙ <span>Waypoint</span></RouterLink><div class="auth-story-copy"><p class="auth-eyebrow">What happens next</p><ol class="auth-steps"><li v-for="(step,i) in steps" :key="step" :style="{'--step-index':i}"><span>{{i+1}}</span><strong>{{step}}</strong></li></ol></div></aside><main class="auth-main"><div class="auth-form-wrap"><RouterLink to="/" class="auth-mobile-brand">↙ Waypoint</RouterLink><p class="auth-eyebrow">{{mode==='register'?'Choose your path':'Waypoint'}}</p><h1>{{title}}</h1><p v-if="mode==='register'" class="auth-lede">A considered path for students asking what comes next, and mentors willing to share context.</p><form v-if="mode!=='register'" @submit.prevent="submit"><label v-if="mode==='student'||mode==='mentor'">Name<input v-model="name" required autocomplete="name"/></label><label>Email<input v-model="email" type="email" required autocomplete="email"/></label><label v-if="mode!=='forgot'">Password<input v-model="password" type="password" required autocomplete="current-password"/></label><button class="btn btn-accent" type="submit">{{mode==='forgot'?'Send reset link':mode==='reset'?'Set new password':'Continue'}} ↗</button><p v-if="submitted" class="form-success" role="status">This frontend demo has recorded the action.</p></form><div v-else-if="mode==='register'" class="role-choice"><RouterLink to="/register/student" class="choice-card"><b>Student</b><span>Ask a question and request considered guidance.</span> →</RouterLink><RouterLink to="/register/mentor" class="choice-card"><b>Mentor</b><span>Share experience on your terms.</span> →</RouterLink></div><div class="auth-footer"><RouterLink v-if="mode==='sign-in'" to="/forgot-password">Forgot password?</RouterLink><RouterLink v-if="mode!=='sign-in'" to="/sign-in">Already have an account? Sign in</RouterLink><RouterLink to="/privacy">Privacy by design</RouterLink></div></div></main></div></template>
